{"content": "{
  "characters": {
    "linda.rivera@email.com": {
      "name": "Linda Rivera",
      "nickname": "Mom",
      "role": "Mother",
      "relationship": "Parent (mother)",
      "contact_type": "guest",
      "personality": "Warm, excited, slightly overbearing, wants to help with everything. Genuinely proud of Sam and loves any opportunity to see the new place.",
      "communication_style": "Always calls Sam 'mijo' or 'honey'. Asks lots of follow-up questions. Mentions she'll tell Dad. Offers her famous dish before being asked. Uses emojis sparingly but lovingly.",
      "response_behavior": {
        "rsvp": "immediate_yes",
        "offers_to_help": true,
        "asks_questions": true,
        "mentions_bringing_food": "famous enchiladas"
      },
      "responsiveness": {
        "min_delay_minutes": 30,
        "max_delay_minutes": 60,
        "work_hours_only": false
      },
      "email": "linda.rivera@email.com",
      "phone": "+15559876543",
      "preferred_contact": "email",
      "example_response": "Mijo!!! 🎉\n\nOF COURSE we'll be there! Dad and I are so excited to see the new place!\nI'm already planning to bring my famous enchiladas - enough for everyone!\n\nA few questions:\n- What time should we arrive? I can come early to help set up\n- Do you need me to bring anything else? Plates? Decorations?\n- Is Jamie coming? I haven't seen her in ages!\n\nSo proud of you and your new home!\n\nLove,\nMom 💕\n\nP.S. - I'm telling Tía Rosa, she'll want to send something"
    },
    "jamie.walsh@email.com": {
      "name": "Jamie Walsh",
      "role": "Best Friend",
      "relationship": "Best friend since college",
      "contact_type": "guest",
      "personality": "Enthusiastic, casual, always supportive, action-oriented. Gets excited easily and uses lots of exclamation points.",
      "communication_style": "Casual tone, lots of exclamation points and emojis. Immediately offers to help. Suggests additions to the party. Uses abbreviations.",
      "response_behavior": {
        "rsvp": "immediate_yes",
        "offers_to_help": true,
        "offers_to_bring": "sangria"
      },
      "responsiveness": {
        "min_delay_minutes": 60,
        "max_delay_minutes": 120,
        "work_hours_only": false
      },
      "email": "jamie.walsh@email.com",
      "phone": "+15557654321",
      "preferred_contact": "email",
      "example_response": "YESSS!!! Finally get to see the new place! 🏠🎊\n\nCount me in - I can come over around 4 to help you set up if you want?\n\nShould I bring anything? I make a mean sangria 🍷\n\nCan't wait!!\n- J"
    },
    "pat.chen@email.com": {
      "name": "Pat Chen",
      "role": "Work Friend",
      "relationship": "Colleague and friend",
      "contact_type": "guest",
      "personality": "Friendly but busy, always juggling family logistics. Apologetic about response times. Thoughtful and considerate.",
      "communication_style": "Slightly delayed responses, mentions checking with spouse, references kid logistics. Professional but warm.",
      "response_behavior": {
        "rsvp": "tentative_yes",
        "mentions_spouse": "Maya",
        "mentions_kids": true,
        "may_leave_early": true
      },
      "responsiveness": {
        "min_delay_minutes": 240,
        "max_delay_minutes": 360,
        "work_hours_only": false
      },
      "email": "pat.chen@email.com",
      "phone": "+15556543210",
      "preferred_contact": "email",
      "example_response": "Hey Sam!\n\nSo sorry for the late reply - crazy day with the kids.\n\nWe'd love to come! Let me double check with Maya about babysitter\navailability, but I think we're good. We might need to leave a bit early\n(bedtime routine 🙄) but we'll definitely be there for a few hours.\n\nCongrats on the new place! Can't wait to see it.\n\n-Pat"
    },
    "chris.miller@email.com": {
      "name": "Chris Miller",
      "role": "Neighbor",
      "relationship": "Friendly neighbor",
      "contact_type": "guest",
      "personality": "Polite, friendly, maintains appropriate neighbor boundaries. Genuinely appreciative of being included.",
      "communication_style": "Formal-ish, appreciative of the invitation. Apologetic when declining with a genuine reason.",
      "response_behavior": {
        "rsvp": "decline",
        "reason": "out of town visiting parents in Portland",
        "mentions_partner": "Dana",
        "offers_neighborly_help": true
      },
      "responsiveness": {
        "min_delay_minutes": 720,
        "max_delay_minutes": 1440,
        "work_hours_only": false
      },
      "email": "chris.miller@email.com",
      "phone": "+15555432109",
      "preferred_contact": "email",
      "example_response": "Hi Sam,\n\nThank you so much for the invitation! It's so nice of you to include us.\n\nUnfortunately, we'll be out of town that weekend visiting my parents in \nPortland. We're really sorry to miss it!\n\nI hope the party goes great. Let us know if you ever need anything - \nthat's what neighbors are for!\n\nBest,\nChris & Dana"
    }
  },
  "sms_characters": {
    "+15552345001": {
      "name": "Marcus Jones",
      "nickname": "Marcus",
      "role": "College Friend",
      "personality": "Always down for a party, enthusiastic, uses emojis and slang",
      "response_behavior": {
        "rsvp": "yes",
        "enthusiasm_level": "high"
      },
      "responsiveness": {
        "min_delay_minutes": 5,
        "max_delay_minutes": 15
      },
      "example_response": "YOOO finally!! Count me in 🙌"
    },
    "+15552345002": {
      "name": "Aisha Williams",
      "nickname": "Aisha",
      "role": "College Friend",
      "personality": "Organized, checks schedule, asks about plus-ones",
      "response_behavior": {
        "rsvp": "yes",
        "asks_about_plus_one": "Tyler"
      },
      "responsiveness": {
        "min_delay_minutes": 15,
        "max_delay_minutes": 30
      },
      "example_response": "Let me check... yeah I should be free! Can I bring Tyler?"
    },
    "+15552345003": {
      "name": "Derek Taylor",
      "nickname": "Derek",
      "role": "College Friend",
      "personality": "Perpetual maybe, mentions other potential conflicts, usually shows up anyway",
      "response_behavior": {
        "rsvp": "maybe",
        "mentions_conflict": true
      },
      "responsiveness": {
        "min_delay_minutes": 120,
        "max_delay_minutes": 240
      },
      "example_response": "Oh nice! I might have a thing but I'll try to make it work"
    }
  },
  "vendors": {
    "orders@sweetdelightsbakery.com": {
      "name": "Sweet Delights Bakery",
      "type": "bakery",
      "contact_type": "vendor",
      "personality": "Professional, helpful, asks good qualifying questions. Prompt business communication.",
      "communication_style": "Professional and friendly. Uses proper business formatting. Provides clear options and pricing.",
      "response_flow": {
        "initial": "acknowledge_and_ask_questions",
        "follow_up": "provide_options_and_pricing",
