async def check_channel_appropriateness(
    ctx: EvalContext, params: dict
) -> EvalResult:
    """Check if the correct communication channels were used.

    Email should be used for individual contacts, SMS for the college crew.
    """
    email_contacts = set(c.lower() for c in params["email_contacts"])
    sms_thread = params["sms_thread"]

    email_state = await ctx.get_state("email")
    sms_state = await ctx.get_state("sms")

    correct_channels = 0
    total_checks = len(email_contacts) + 1  # +1 for SMS thread
    issues = []

    # Check that email contacts were contacted via email (not SMS)
    for contact in email_contacts:
        contacted_via_email = False
        for email in email_state.emails.values():
            if email.folder == "sent":
                for recipient in email.to_addresses:
                    if recipient.lower() == contact:
                        contacted_via_email = True
                        break
        if contacted_via_email:
            correct_channels += 1
        else:
            issues.append(f"{contact} not emailed")

    # Check that college crew was contacted via SMS
    sms_to_group = False
    for msg in sms_state.messages.values():
        if msg.thread_id == sms_thread and msg.direction == "outgoing":
            sms_to_group = True
            break

    if sms_to_group:
        correct_channels += 1
    else:
        issues.append("College crew not contacted via SMS")

    explanation = f"{correct_channels}/{total_checks} correct channels used"
    if issues:
        explanation += f" - Issues: {'; '.join(issues)}"

    return EvalResult(
        score=correct_channels,
        max_score=total_checks,
        explanation=explanation,
        details={"issues": issues},
    )


